package org.brightstats.stats;
import java.util.*;
import java.util.function.IntConsumer;

/** Shared exploratory PCA over actual model indicators, globally and by measurement block. */
public final class ModelPca {
    private ModelPca(){}
    public enum Context {PLS,CBSEM,GSCA}
    public enum Retention {FIXED,KAISER,VARIANCE}
    public record Group(String name,List<String> indicators){public Group{if(name==null||name.isBlank()||indicators.isEmpty()||new HashSet<>(indicators).size()!=indicators.size())throw new IllegalArgumentException("PCA groups need a name and distinct indicators.");indicators=List.copyOf(indicators);}}
    public record Source(Context context,List<String> indicators,List<Group> groups){public Source{Objects.requireNonNull(context);indicators=List.copyOf(indicators);groups=List.copyOf(groups);if(indicators.isEmpty()||new HashSet<>(indicators).size()!=indicators.size()||groups.size()>64||groups.stream().map(Group::name).distinct().count()!=groups.size())throw new IllegalArgumentException("Model PCA needs distinct model indicators and at most 64 uniquely named groups.");for(var group:groups)if(!indicators.containsAll(group.indicators()))throw new IllegalArgumentException("PCA group contains an indicator outside the model.");}}
    public record Options(boolean correlation,Retention retention,int components,double varianceThreshold,PcaRotation.Options rotation){public Options{Objects.requireNonNull(retention);Objects.requireNonNull(rotation);if(components<1||components>512||!Double.isFinite(varianceThreshold)||varianceThreshold<=0||varianceThreshold>1)throw new IllegalArgumentException("Choose 1–512 fixed components and a variance threshold in (0,1].");if(retention==Retention.KAISER&&!correlation)throw new IllegalArgumentException("The eigenvalue-one rule requires correlation PCA; use fixed count or cumulative variance for covariance PCA.");}public static Options defaults(){return new Options(true,Retention.KAISER,3,.95,PcaRotation.Options.defaults());}}
    public record GroupFit(String name,List<String> indicators,List<Integer> columns,PrincipalComponents.Fit pca,PcaRotation.Fit rotation,List<String> warnings){public GroupFit{indicators=List.copyOf(indicators);columns=List.copyOf(columns);warnings=List.copyOf(warnings);}}
    public record Fit(Source source,Options options,List<GroupFit> groups,List<String> warnings){public Fit{groups=List.copyOf(groups);warnings=List.copyOf(warnings);}}
    public static Source fromPls(List<String> names,List<PlsSem.Block> blocks){List<Group> groups=new ArrayList<>();LinkedHashSet<String> used=new LinkedHashSet<>();for(var block:blocks){List<String> indicators=new ArrayList<>();for(int column:block.columns()){if(column<0||column>=names.size())throw new IllegalArgumentException("PLS indicator is outside the dataset.");indicators.add(names.get(column));}groups.add(new Group(block.name(),indicators));used.addAll(indicators);}return new Source(Context.PLS,List.copyOf(used),groups);}
    public static Source fromGsca(Gsca.Model model){List<Group> groups=new ArrayList<>();boolean[][] weights=model.weights(),loadings=model.loadings();for(int component=0;component<model.components().size();component++){List<String> indicators=new ArrayList<>();for(int indicator=0;indicator<model.indicators().size();indicator++)if(weights[indicator][component]||loadings[indicator][component])indicators.add(model.indicators().get(indicator));groups.add(new Group(model.components().get(component),indicators));}return new Source(Context.GSCA,model.indicators(),groups);}
    public static Source fromSem(SemModel.Model model){Set<Integer> observed=new HashSet<>();List<String> indicators=new ArrayList<>();for(int index:model.observed()){observed.add(index);indicators.add(model.variables().get(index));}double[][] directed=model.directed();Set<String> free=new HashSet<>();for(var parameter:model.parameters())for(var location:parameter.locations())if(location.kind()==SemModel.Kind.DIRECTED)free.add(location.row()+":"+location.column());List<Group> groups=new ArrayList<>();for(int factor=0;factor<model.variables().size();factor++)if(!observed.contains(factor)){List<String> measured=new ArrayList<>();for(int indicator:model.observed())if(directed[indicator][factor]!=0||free.contains(indicator+":"+factor))measured.add(model.variables().get(indicator));if(!measured.isEmpty())groups.add(new Group(model.variables().get(factor),measured));}return new Source(Context.CBSEM,indicators,groups);}
    public static Fit fit(double[][] data,List<String> names,Source source,Options options,IntConsumer progress){
        Matrices.interrupted();int width=Matrices.width(data,2);if(names.size()!=width||new HashSet<>(names).size()!=names.size())throw new IllegalArgumentException("Model PCA requires unique dataset column names.");
        List<Group> definitions=new ArrayList<>();definitions.add(new Group("All model indicators",source.indicators()));for(var group:source.groups())definitions.add(new Group("Construct: "+group.name(),group.indicators()));
        long cells=0;for(var definition:definitions){if(definition.indicators().size()>512)throw new IllegalArgumentException("Dense model PCA is limited to 512 indicators per group.");cells+=(long)data.length*definition.indicators().size();}if(cells>5_000_000)throw new IllegalArgumentException("Model PCA exceeds five million selected data cells across groups.");
        List<GroupFit> results=new ArrayList<>();int completed=0;for(var definition:definitions){Matrices.interrupted();List<Integer> columns=definition.indicators().stream().map(names::indexOf).toList();if(columns.contains(-1))throw new IllegalArgumentException("Model indicator missing from the dataset in "+definition.name());double[][] selected=new double[data.length][columns.size()];for(int row=0;row<data.length;row++)for(int col=0;col<columns.size();col++)selected[row][col]=data[row][columns.get(col)];List<String> warnings=new ArrayList<>();
            int retained=Math.min(options.components(),columns.size());PrincipalComponents.Fit point;if(options.retention()==Retention.FIXED){if(options.components()>columns.size())warnings.add("Requested fixed count clipped to this group's indicator count.");point=PrincipalComponents.fit(selected,options.correlation(),retained);}else{var full=PrincipalComponents.fit(selected,options.correlation(),columns.size());retained=0;if(options.retention()==Retention.KAISER){for(double eigenvalue:full.eigenvalues())if(eigenvalue>1)retained++;if(retained==0){retained=1;warnings.add("No eigenvalue exceeds one. One axis is retained only to provide an exploratory summary, not evidence of a substantive dimension.");}}else{double cumulative=0;for(double ratio:full.explainedRatio()){retained++;cumulative+=ratio;if(cumulative>=options.varianceThreshold()-1e-12)break;}}point=retain(full,retained);}
            PcaRotation.Fit rotation=null;if(options.rotation().method()!=PcaRotation.Method.NONE)try{rotation=PcaRotation.rotate(point,options.rotation());}catch(IllegalArgumentException problem){throw new IllegalArgumentException(definition.name()+": "+problem.getMessage(),problem);}warnings.addAll(rotation==null?point.warnings():rotation.warnings());results.add(new GroupFit(definition.name(),definition.indicators(),columns,point,rotation,warnings));if(progress!=null)progress.accept(++completed);}
        return new Fit(source,options,results,List.of("PCA is exploratory. Model groups select observed indicators; this procedure does not estimate structural paths, confirm a measurement model, or validate causal claims.","The all-indicator analysis contains each model indicator once. Cross-loaded indicators can appear in multiple separate construct analyses. Kaiser retention uses eigenvalues strictly greater than one; it is a heuristic, not a significance test. Variance retention refers to the unrotated PCA."));
    }
    private static PrincipalComponents.Fit retain(PrincipalComponents.Fit full,int count){double[][] vectors=full.vectors(),loadings=full.loadings(),scores=full.scores();for(int row=0;row<vectors.length;row++){vectors[row]=Arrays.copyOf(vectors[row],count);loadings[row]=Arrays.copyOf(loadings[row],count);}for(int row=0;row<scores.length;row++)scores[row]=Arrays.copyOf(scores[row],count);return new PrincipalComponents.Fit(full.correlation(),count,full.means(),full.scales(),full.eigenvalues(),full.explainedRatio(),vectors,loadings,scores,full.warnings());}
}
